import{_ as s,C as r,o as n,c as o,j as t,a as i,G as p,aj as l}from"./chunks/framework.BZR1KcQy.js";const b=JSON.parse('{"title":"GNS3","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/gns3.md","filePath":"docs/wi/gns3.md","lastUpdated":1788528169000}'),c={name:"docs/wi/gns3.md"};function d(g,e,h,m,u,k){const a=r("ImageZoom");return n(),o("div",null,[e[0]||(e[0]=t("h1",{id:"gns3",tabindex:"-1"},[i("GNS3 "),t("a",{class:"header-anchor",href:"#gns3","aria-label":'Permalink to "GNS3"'},"​")],-1)),p(a,{src:"https://i0.wp.com/brianlinkletter.com/wp-content/uploads/2015/07/GNS3-v1x-064.png?fit=833%2C582&ssl=1"}),e[1]||(e[1]=l('<p>GNS3 — это мощная кроссплатформенная платформа для эмуляции сетей, позволяющая проектировать, настраивать и тестировать сложные сети любой масштабируемости в виртуальной среде. Она использует реальные образы сетевых устройств (в первую очередь Cisco IOS/IOSv, но также поддерживает устройства других вендоров, таких как Juniper, Arista и Linux-маршрутизаторы), запуская их либо на локальном компьютере, либо распределяя нагрузку на внешние серверы или облако. GNS3 идеально подходит для сетевых инженеров, администраторов и студентов, предоставляя инструменты для обучения, подготовки к сертификациям (CCNA, CCNP, CCIE), тестирования конфигураций перед внедрением в продакшн и моделирования сценариев без риска для работающей сети, интегрируясь при этом с реальным оборудованием, VMware/VirtualBox и облачными провайдерами.</p><div class="danger custom-block"><p class="custom-block-title">ВНИМАНИЕ! Подстава!</p><p>Последняя версия GNS3 в репозитории Альт - 2.2.60, а последняя версия в целом 3.1.0 (<a href="https://repology.org/project/gns3-gui/versions" target="_blank" rel="noreferrer">https://repology.org/project/gns3-gui/versions</a>), соответственно, будьте внимательны с версией GNS3 VM. Если будет несовпадение, то и работать не будет</p></div><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gns3</span></span></code></pre></div><p>Чтобы подключить GNS3 VM Должен быть включен локальный или удалённый сервер на вкладке Server</p><p>Ссылка на <a href="https://github.com/GNS3/gns3-vm/tree/v0.15.0" target="_blank" rel="noreferrer">GNS3 VM</a></p><p>У меня есть Template с Альт Линуксом для GNS3 <a href="https://github.com/bysnik/community-alt-gns3" target="_blank" rel="noreferrer">https://github.com/bysnik/community-alt-gns3</a></p>',7))])}const N=s(c,[["render",d]]);export{b as __pageData,N as default};
